// Categorize Discord message and route to right department
const msg = $input.item.json.body.content;
let category = 'general';
let department = 'general-support';

if (msg.toLowerCase().includes('urgent') || msg.toLowerCase().includes('error') || msg.toLowerCase().includes('broken')) {
  category = 'urgent';
  department = 'it-support';
} else if (msg.toLowerCase().includes('success') || msg.toLowerCase().includes('thanks') || msg.toLowerCase().includes('love')) {
  category = 'success-story';
  department = 'customer-success';
} else if (msg.includes('?')) {
  category = 'question';
  department = 'customer-support';
}

return {
  json: {
    original_message: msg,
    category: category,
    department: department,
    user: $input.item.json.body.author.username,
    channel: $input.item.json.body.channel_id,
    timestamp: new Date().toISOString()
  }
};
